"""Read the delivered fragment catalogue without changing source records."""
import hashlib
import json

def checksum(coefficients, value):
    body = json.dumps({'coefficients': coefficients, 'value': value}, sort_keys=True, separators=(',', ':')).encode()
    return hashlib.sha256(body).hexdigest()

def active_fragments(request):
    revisions = {}; latest = {}
    for row in request['fragments']:
        key = (row['id'], row['revision'])
        if key in revisions and revisions[key] != row: raise ValueError('conflicting catalogue revision')
        revisions[key] = row
        if row['id'] not in latest or row['revision'] > latest[row['id']]['revision']:
            latest[row['id']] = row
    return [row for _, row in sorted(latest.items())
            if row['live'] and (row['tenant'], row['generation']) == (request['tenant'], request['generation'])
            and checksum(row['coefficients'], row['value']) == row['sha256']]

"""Decoder for small generation records."""
from itertools import combinations
from .catalog import active_fragments
from .field import dot, solutions

class RestoreError(ValueError):
    pass

def recover(request):
    rows = [(r['coefficients'], r['value']) for r in active_fragments(request)]
    budget = min(request['fault_budget'], len(rows))
    candidates = set()
    # The deployed decoder's omission loop predates the latest format revision.
    for omitted in combinations(range(len(rows)), min(budget, 1)):
        retained = [row for i, row in enumerate(rows) if i not in omitted]
        for value in solutions(retained, request['width']):
            if sum(dot(c, value) != v for c, v in rows) <= budget:
                candidates.add(value)
    if len(candidates) != 1:
        raise RestoreError('the supplied records do not establish a unique generation')
    return next(iter(candidates))

"""GF(256) arithmetic used by the generation storage format."""
import itertools

def multiply(a, b):
    result = 0
    while b:
        if b & 1: result ^= a
        a <<= 1
        if a & 256: a ^= 0x11b
        b >>= 1
    return result

def power(a, n):
    result = 1
    while n:
        if n & 1: result = multiply(result, a)
        a = multiply(a, a); n >>= 1
    return result

def dot(coefficients, values):
    result = 0
    for a, b in zip(coefficients, values): result ^= multiply(a, b)
    return result

def solutions(rows, width):
    matrix = [list(c) + [v] for c, v in rows]
    pivots = []; rank = 0
    for column in range(width):
        pivot = next((i for i in range(rank, len(matrix)) if matrix[i][column]), None)
        if pivot is None: continue
        matrix[rank], matrix[pivot] = matrix[pivot], matrix[rank]
        inverse = power(matrix[rank][column], 254)
        matrix[rank] = [multiply(x, inverse) for x in matrix[rank]]
        for i in range(len(matrix)):
            if i != rank and matrix[i][column]:
                factor = matrix[i][column]
                matrix[i] = [a ^ multiply(factor, b) for a, b in zip(matrix[i], matrix[rank])]
        pivots.append(column); rank += 1
    if any(not any(row[:width]) and row[-1] for row in matrix): return []
    free = [i for i in range(width) if i not in pivots]
    if len(free) > 1: raise ValueError('unsupported encoding profile')
    result = []
    for values in itertools.product(range(256), repeat=len(free)):
        decoded = [0] * width
        for i, value in zip(free, values): decoded[i] = value
        for row, pivot in zip(matrix, pivots): decoded[pivot] = row[-1] ^ dot(row[:width], decoded)
        result.append(bytes(decoded))
    return result

