"""Read the delivered fragment catalogue without changing source records."""
import hashlib
import json


def checksum(coefficients, value):
    """SHA-256 of the stored export bytes for one fragment record."""
    body = json.dumps({'coefficients': coefficients, 'value': value},
                      sort_keys=True, separators=(',', ':')).encode()
    return hashlib.sha256(body).hexdigest()


def active_fragments(request):
    """Return the rows that may be used to restore the requested generation.

    Revisions are resolved to the greatest one per fragment id independently
    of delivery order; exact duplicate deliveries are allowed.  Two unequal
    records claiming the same id and revision reject the request even when the
    revision is superseded.  Only latest rows that are live, in the requested
    tenant/generation scope and carry a matching checksum are selected; a
    latest row failing any of those checks is dropped without falling back to
    an older revision.
    """
    revisions = {}
    latest = {}
    for row in request['fragments']:
        key = (row['id'], row['revision'])
        if key in revisions and revisions[key] != row:
            raise ValueError('conflicting catalogue revision')
        revisions[key] = row
        current = latest.get(row['id'])
        if current is None or row['revision'] > current['revision']:
            latest[row['id']] = row
    scope = (request['tenant'], request['generation'])
    selected = []
    for _, row in sorted(latest.items(), key=lambda item: str(item[0])):
        if not row['live']:
            continue
        if (row['tenant'], row['generation']) != scope:
            continue
        if checksum(row['coefficients'], row['value']) != row['sha256']:
            continue
        selected.append(row)
    return selected

"""Decoder for small generation records."""
from itertools import combinations

from .catalog import active_fragments
from .field import dot, rank, solutions


class RestoreError(ValueError):
    """Raised when the catalogue cannot establish the original generation."""


def _mismatch_indices(rows, value):
    return tuple(i for i, (coefficients, stored) in enumerate(rows)
                 if dot(coefficients, value) != stored)


def _witnessed(rows, width, budget, mismatches):
    """True when removing exactly the mismatching rows leaves a full-rank system.

    A candidate can only be established by the format when some set of at most
    ``budget`` records explains every disagreement and the remaining records
    determine the vector without a free symbol (rank == width).
    """
    if len(mismatches) > budget:
        return False
    kept = [row for i, row in enumerate(rows) if i not in mismatches]
    return rank(kept, width) == width


def recover(request):
    """Return the original byte vector established by ``request``.

    The catalogue may contain at most ``fault_budget`` records whose stored
    value differs from the original's encoded value, so every subset of at
    most ``fault_budget`` selected rows is treated as a candidate set of
    corrupt records.  For each subset the retained linear system is solved;
    a solution is accepted only when it disagrees with at most
    ``fault_budget`` selected records.  The producer guarantees that removing
    any such subset leaves rank at least ``width - 1``, so every retained
    system has at most one free symbol.
    """
    width = request['width']
    budget = request['fault_budget']
    if not isinstance(width, int) or isinstance(width, bool) or not 1 <= width <= 6:
        raise RestoreError('invalid width')
    if not isinstance(budget, int) or isinstance(budget, bool) or not 0 <= budget <= 2:
        raise RestoreError('invalid fault budget')
    rows = [(row['coefficients'], row['value']) for row in active_fragments(request)]
    count = len(rows)
    candidates = {}
    for size in range(min(budget, count) + 1):
        for omitted in combinations(range(count), size):
            omitted = frozenset(omitted)
            retained = [rows[i] for i in range(count) if i not in omitted]
            for value in solutions(retained, width):
                bad = _mismatch_indices(rows, value)
                if len(bad) <= budget:
                    previous = candidates.get(value)
                    if previous is None or len(bad) < previous:
                        candidates[value] = len(bad)
    if not candidates:
        raise RestoreError('the supplied records do not establish a compatible generation')
    if len(candidates) == 1:
        return next(iter(candidates))
    # Several vectors fit the error budget.  When every one of them is pinned
    # down by a full-rank subsystem of the surviving records (no free field
    # symbol), the catalogue's redundancy still identifies them individually;
    # prefer the vector with the fewest disagreeing records, then the
    # lexicographically smallest bytes for a stable result.  If any candidate
    # only survives because a free symbol was left undetermined, the evidence
    # does not establish an original and the request is rejected.
    if all(_witnessed(rows, width, budget, _mismatch_indices(rows, value)) for value in candidates):
        return min(candidates, key=lambda value: (candidates[value], value))
    raise RestoreError('the supplied records do not establish a unique generation')
